package com.videocalllive.app;
import android.app.*;import android.graphics.*;import android.graphics.drawable.*;import android.view.*;import android.widget.*;
public class Ui{
 public static final int BG=Color.rgb(12,8,24), CARD=Color.rgb(31,22,48), PINK=Color.rgb(244,48,133), TEXT=Color.WHITE, MUTED=Color.rgb(190,184,205);
 public static int dp(Activity a,int v){return (int)(v*a.getResources().getDisplayMetrics().density+.5f);}
 public static GradientDrawable bg(int color,float radius){GradientDrawable g=new GradientDrawable();g.setColor(color);g.setCornerRadius(radius);return g;}
 public static Drawable appBackground(){GradientDrawable g=new GradientDrawable(GradientDrawable.Orientation.TL_BR,new int[]{Color.rgb(12,8,24),Color.rgb(38,17,61),Color.rgb(55,18,58),Color.rgb(15,9,28)});g.setGradientType(GradientDrawable.LINEAR_GRADIENT);return g;}
 public static LinearLayout root(Activity a){LinearLayout r=new LinearLayout(a);r.setOrientation(LinearLayout.VERTICAL);r.setPadding(dp(a,16),dp(a,14),dp(a,16),dp(a,10));r.setBackground(appBackground());return r;}
 public static LinearLayout backTitle(Activity a,String s){LinearLayout row=new LinearLayout(a);row.setGravity(Gravity.CENTER_VERTICAL);Button back=new Button(a);back.setText("←");back.setTextSize(34);back.setTypeface(Typeface.DEFAULT,Typeface.BOLD);back.setTextColor(TEXT);back.setBackgroundColor(Color.TRANSPARENT);back.setPadding(0,0,0,0);back.setOnClickListener(v->a.finish());LinearLayout.LayoutParams bp=new LinearLayout.LayoutParams(dp(a,54),dp(a,54));bp.topMargin=-dp(a,6);row.addView(back,bp);TextView t=title(a,s);row.addView(t,new LinearLayout.LayoutParams(0,-2,1));return row;}
 public static TextView title(Activity a,String s){TextView t=new TextView(a);t.setText(s);t.setTextSize(27);t.setTextColor(TEXT);t.setTypeface(Typeface.DEFAULT,Typeface.BOLD);t.setPadding(0,dp(a,8),0,dp(a,10));return t;}
 public static TextView body(Activity a,String s){TextView t=new TextView(a);t.setText(s);t.setTextSize(15);t.setTextColor(MUTED);t.setPadding(0,dp(a,3),0,dp(a,7));return t;}
 public static Button button(Activity a,String s){Button b=new Button(a);b.setText(s);b.setAllCaps(false);b.setTextSize(16);b.setTypeface(Typeface.DEFAULT,Typeface.BOLD);b.setTextColor(TEXT);b.setBackground(bg(PINK,dp(a,18)));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,dp(a,54));p.setMargins(0,dp(a,7),0,dp(a,7));b.setLayoutParams(p);return b;}
 public static Button secondary(Activity a,String s){Button b=button(a,s);GradientDrawable g=bg(CARD,dp(a,18));g.setStroke(dp(a,1),Color.rgb(64,66,82));b.setBackground(g);b.setTextColor(TEXT);return b;}
 public static EditText input(Activity a,String h){EditText e=new EditText(a);e.setHint(h);e.setHintTextColor(Color.rgb(125,128,143));e.setTextColor(TEXT);e.setSingleLine(true);GradientDrawable g=bg(CARD,dp(a,16));g.setStroke(dp(a,1),Color.rgb(58,60,76));e.setBackground(g);e.setPadding(dp(a,16),0,dp(a,16),0);LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,dp(a,54));p.setMargins(0,dp(a,6),0,dp(a,8));e.setLayoutParams(p);return e;}
 public static LinearLayout card(Activity a){LinearLayout c=new LinearLayout(a);c.setOrientation(LinearLayout.VERTICAL);c.setPadding(dp(a,14),dp(a,14),dp(a,14),dp(a,14));c.setBackground(bg(CARD,dp(a,20)));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.setMargins(0,dp(a,7),0,dp(a,7));c.setLayoutParams(p);return c;}
 public static TextView avatar(Activity a,String name){TextView v=new TextView(a);v.setText(name.substring(0,1));v.setTextColor(TEXT);v.setTextSize(34);v.setTypeface(Typeface.DEFAULT,Typeface.BOLD);v.setGravity(Gravity.CENTER);v.setBackground(bg(Color.rgb(115,55,155),dp(a,20)));v.setLayoutParams(new LinearLayout.LayoutParams(-1,dp(a,155)));return v;}
 public static LinearLayout nav(Activity a,String active){LinearLayout nav=new LinearLayout(a);nav.setOrientation(LinearLayout.HORIZONTAL);nav.setPadding(0,dp(a,4),0,0);String[] labels={"⌂\nHome","☏\nChats","▣\nVideo","◎\nCoins","♙\nProfile"};for(int i=0;i<labels.length;i++){String s=labels[i];Button b=new Button(a);b.setAllCaps(false);b.setText(s);b.setTextSize(12);b.setTextColor(s.contains(active)?PINK:Color.WHITE);b.setBackgroundColor(Color.TRANSPARENT);b.setLayoutParams(new LinearLayout.LayoutParams(0,dp(a,64),1));if(i==3 && "female".equals(a.getSharedPreferences("vcl",0).getString("gender",""))) b.setVisibility(View.GONE);nav.addView(b);}return nav;}
 public static void toast(Activity a,String s){Toast.makeText(a,s,Toast.LENGTH_SHORT).show();}
}
